package api

import "github.com/gin-gonic/gin"

const indexPage = `<!doctype html>
<html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>标题解析</title>
<style>:root{font:16px/1.5 system-ui,sans-serif;color:#17202a;background:#eef2f5}body{margin:0;padding:40px 16px}main{max-width:860px;margin:auto}header,.panel{background:#fff;border:1px solid #d5dde5;box-shadow:6px 6px #c5d1dc;padding:28px}h1{margin:0 0 6px;font-size:30px}p{margin:0 0 20px;color:#536273}textarea{box-sizing:border-box;width:100%;min-height:120px;padding:12px;font:inherit;border:1px solid #b8c4cf;resize:vertical}button{margin-top:12px;padding:10px 18px;border:0;background:#1769aa;color:#fff;font:inherit;cursor:pointer}button:focus-visible,textarea:focus-visible{outline:3px solid #f0a202;outline-offset:2px}#error{margin-top:16px;color:#b42318}.panel{margin-top:24px}.content{font-size:25px;font-weight:650;word-break:break-word}.muted{color:#536273}.section{margin-top:22px}.section h2{margin:0 0 10px;font-size:15px;color:#1769aa;text-transform:uppercase;letter-spacing:.08em}.fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px}.field{padding:11px;background:#f4f7f9;border-left:3px solid #1769aa}.label{display:block;color:#536273;font-size:13px}.value{display:block;margin-top:3px;word-break:break-word}.chips{display:flex;flex-wrap:wrap;gap:7px}.chip{padding:4px 9px;background:#e7eef4;border:1px solid #c8d6e0}@media(max-width:480px){body{padding:20px 12px}header,.panel{padding:18px}.content{font-size:22px}}</style>
<main><header><h1>标题解析</h1><p>输入发布标题，查看完整的主要内容和媒体属性。</p><textarea id="input" placeholder="输入发布标题"></textarea><button id="parse" type="button">解析标题</button><div id="error" role="alert"></div></header><section id="result" class="panel" aria-live="polite"><div class="muted">等待解析</div></section></main>
<script>
const labels={season:'季数',season_range:'季数范围',number:'集数',numbers:'集数列表',special:'特别篇'};
const text=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const chips=v=>'<div class="chips">'+v.map(x=>'<span class="chip">'+text(x)+'</span>').join('')+'</div>';
const field=(name,value)=>value===undefined||value===null||value===''||(Array.isArray(value)&&!value.length)?'':'<div class="field"><span class="label">'+name+'</span><span class="value">'+(Array.isArray(value)?chips(value):text(value))+'</span></div>';
const section=(name,body)=>body?'<div class="section"><h2>'+name+'</h2><div class="fields">'+body+'</div></div>':'';
function render(d){let out='<div class="content">'+text(d.content||'未识别到内容')+'</div>';if(d.aliases?.length)out+='<p class="muted">别名：'+d.aliases.map(text).join(' / ')+'</p>';if(d.groups?.length)out+='<p class="muted">发布组：'+d.groups.map(text).join(' / ')+'</p>';if(d.versions?.length)out+='<p class="muted">发布修订：'+d.versions.map(text).join(' / ')+'</p>';const e=d.episode;if(e){const range=e.range&&((e.range.start||'')+(e.range.end?'-'+e.range.end:''));const alt=e.alternates?.map(x=>[x.season&&'S'+x.season,x.season_range,x.number&&'E'+x.number,x.numbers?.join(','),x.range&&((x.range.start||'')+'-'+(x.range.end||'')),x.special].filter(Boolean).join(' '));out+=section('分集',field(labels.season,e.season)+field(labels.season_range,e.season_range)+field(labels.number,e.number)+field(labels.numbers,e.numbers)+field('集数范围',range)+field(labels.special,e.special)+field('其他分集语义',alt))}const movie=d.movie;if(movie){const range=movie.range&&((movie.range.start||'')+(movie.range.end?'-'+movie.range.end:''));out+=section('电影',field('电影序号',movie.index)+field('电影序号范围',range))}const m=d.media;if(m){const audio=m.audio_tracks?.map(x=>[x.language,x.codec,x.channels,x.object].filter(Boolean).join(' / '));out+=section('视频与来源',field('平台',m.platforms)+field('来源',m.source_types)+field('分辨率',m.resolutions)+field('视频编码',m.video_codecs)+field('色深',m.bit_depths)+field('容器',m.containers)+field('HDR',m.hdr)+field('CRC',m.crcs));out+=section('音频',field('音频标记',m.audio_flags)+field('音轨',audio));if(m.subtitles)out+=section('字幕',field('语言',m.subtitles.languages)+field('类型',m.subtitles.types)+field('格式',m.subtitles.formats))}return out}
document.querySelector('#parse').onclick=async()=>{const input=document.querySelector('#input'),error=document.querySelector('#error'),result=document.querySelector('#result'),title=input.value.trim();error.textContent='';if(!title){result.innerHTML='<div class="muted">请输入标题</div>';return}result.innerHTML='<div class="muted">解析中...</div>';try{const r=await fetch('/api/v1/content',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({title})}),d=await r.json();if(!r.ok)throw Error(d.error||'解析失败');result.innerHTML=render(d)}catch(e){result.innerHTML='';error.textContent=e.message}};
</script>`

func (h *Handler) Page(c *gin.Context) {
	c.Data(200, "text/html; charset=utf-8", []byte(indexPage))
}
